fn cursor(sequence: u64) -> FeedCursor {
    if sequence == 0 {
        FeedCursor::beginning()
    } else {
        FeedCursor {
            lineage: LINEAGE,
            sequence,
        }
    }
}

/// Checks one reader against the literal legacy stream and pages.
fn check_legacy(read: &dyn Fn(&FeedCursor, usize) -> ChangeBatch) {
    let expected = legacy_expected();
    let all = read(&FeedCursor::beginning(), 10_000);
    assert_eq!(all.changes, expected);
    assert_eq!(
        (all.next, all.has_more, all.head),
        (cursor(14), false, 14),
        "full read"
    );
    assert_eq!(
        all.next.to_token(),
        "vlc1.0123456789abcdef.000000000000000e.77659153"
    );
    for (from, events, next, has_more, head, token) in ONE_EVENT_PAGES {
        for limit in [0, 1] {
            let page = read(&cursor(from), limit);
            let got: Vec<(u64, u32)> = page
                .changes
                .iter()
                .map(|change| (change.sequence, change.ordinal))
                .collect();
            assert_eq!(got, events, "page after {from}, limit {limit}");
            for change in &page.changes {
                assert!(expected.contains(change), "page after {from}: {change:?}");
            }
            assert_eq!(
                (page.next, page.has_more, page.head),
                (cursor(next), has_more, head),
                "page after {from}, limit {limit}"
            );
            assert_eq!(page.next.to_token(), token);
            assert_eq!(FeedCursor::from_token(token).unwrap(), cursor(next));
        }
    }
}

